files+=list((ROOT/'field-app/src').rglob('*'))+list((ROOT/'field-app/public').rglob('*'))+[ROOT/'field-app'/n for n in ['package.json','package-lock.json','vite.config.ts','tsconfig.json','index.html','README.md']]
